"""Self-contained GUI asset, included in reproducible zipapp."""
PAGE=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Labinst FRA</title><style>
*{box-sizing:border-box}body{margin:0;background:#edf1f6;color:#17243a;font:16px system-ui}header{padding:15px 24px;background:#17243a;color:white;display:flex;justify-content:space-between}main{padding:18px;display:grid;grid-template-columns:300px 1fr;gap:18px}section{background:white;padding:18px;border-radius:12px}h1{font-size:22px;margin:0}h2{font-size:18px}label{display:flex;justify-content:space-between;align-items:center;gap:8px;margin:10px 0;font-size:14px}input,select{width:145px;padding:8px;border:1px solid #ccd3df;border-radius:5px}button{cursor:pointer;border:0;border-radius:6px;padding:13px;font-weight:bold;background:#dfe6ef}#start{background:#168553;color:white}#stop{background:#bf3030;color:white}button:disabled{opacity:.45;cursor:default}.buttons{display:flex;gap:8px;flex-wrap:wrap;position:sticky;top:8px;background:white;z-index:1;padding:8px 0}#controls{max-height:60vh;overflow-y:auto;margin-top:10px}.badge{background:#805919;padding:5px 10px;border-radius:4px}#plot{width:100%;min-height:300px}pre{white-space:pre-wrap;overflow-wrap:anywhere}#warnings{color:#a32820;font-weight:600}#stats{font:17px ui-monospace,monospace;line-height:1.8}progress{width:100%}.exports{display:flex;gap:15px;margin:15px 0}.note{font-size:12px;color:#58667a}details{margin-top:12px}@media(max-width:850px){main{grid-template-columns:1fr}#controls{display:grid;grid-template-columns:1fr 1fr;gap:8px}label{flex-wrap:wrap}}@media(max-width:480px){#controls{display:block}}
</style><header><h1>FRA / Bode analyzer</h1><span id="trust" class="badge">UNTRUSTED</span></header><main><section><h2>Measurement</h2><form id="form"><div class="buttons"><button type="button" id="start">START SWEEP</button><button type="button" id="single">SINGLE POINT</button><button type="button" id="stop">STOP</button></div><p class="note">AWG amplitude [mVpp]</p><div class="buttons amplitude-buttons"><button type="button" data-amplitude-factor="0.5">÷2</button><button type="button" data-amplitude-mv="10">10 mVpp</button><button type="button" data-amplitude-mv="20">20 mVpp</button><button type="button" data-amplitude-mv="50">50 mVpp</button><button type="button" data-amplitude-factor="2">×2</button></div><div id="controls"></div></form><p class="note">Amplitude is programmed AWG mVpp, not a measured DUT voltage. Limits and generator readback still apply. Changes take effect on the next START/SINGLE POINT. H uses measured Vin and Vout. Single point uses start frequency. STOP requests AWG OFF; cleanup confirmation appears below.</p><button id="savePreset">Save preset</button><label>Load preset<input type="file" id="loadPreset" accept=".json"></label></section><section><h2 id="state">Idle</h2><progress id="progress" value="0" max="1"></progress><pre id="stats">No measurement yet</pre><div id="warnings" role="alert"></div><img id="plot" alt="Live magnitude and phase Bode plots"><div class="exports"><a href="/api/export/json">JSON</a><a href="/api/export/csv">CSV</a><a href="/api/export/png">PNG</a><a href="/api/export/svg">SVG</a></div><details><summary>Instrument identities and cleanup</summary><pre id="details"></pre></details></section></main><script>
const $=id=>document.getElementById(id);let token='__TOKEN__',config={},defaults={},lastRevision=-1;
const labels={source:'AWG device:channel',input:'Scope input',output:'Scope output',start_frequency:'Start [Hz]',stop_frequency:'Stop [Hz]',points:'Points (blank = per decade)',points_per_decade:'Points per decade',spacing:'Spacing',amplitude:'AWG amplitude [mVpp]',averages:'Averages',cycles_per_record:'Cycles / record',settling_cycles:'Settling cycles',minimum_settling_s:'Min settling [s]',sample_rate:'Sample rate [Sa/s] / auto',samples_per_cycle:'Samples / cycle',minimum_input_rms:'Minimum Vin [mVrms]',volts_per_div:'Scope [mV/div]',acquisition_timeout_s:'Acquisition timeout [s]'};
const displayScale={amplitude:1000,volts_per_div:1000,minimum_input_rms:1000};
function populate(c){config=c;$('controls').replaceChildren();for(const [k,v]of Object.entries(c)){let lab=document.createElement('label');lab.append(document.createTextNode(labels[k]||k));let el=document.createElement(k==='spacing'?'select':'input');el.id='c_'+k;if(k==='spacing'){for(const s of ['log','linear']){let o=document.createElement('option');o.value=s;o.textContent=s;el.append(o)}}else{el.type=['source','input','output','sample_rate'].includes(k)?'text':'number';el.step='any'}el.value=v===null?'':typeof v==='number'?Number((v*(displayScale[k]||1)).toPrecision(12)):v;lab.append(el);$('controls').append(lab)}}
function readConfig(){let c={};for(const k of Object.keys(config)){let v=$('c_'+k).value;c[k]=['source','input','output','spacing'].includes(k)?v:k==='sample_rate'&&v==='auto'?'auto':k==='points'&&v===''?null:Number(v)/(displayScale[k]||1)}return c}
for(const button of document.querySelectorAll('.amplitude-buttons button'))button.onclick=()=>{const el=$('c_amplitude');if(!el||el.disabled)return;const value=button.dataset.amplitudeMv?Number(button.dataset.amplitudeMv):Number(el.value)*Number(button.dataset.amplitudeFactor);if(!Number.isFinite(value)||value<=0){fail(Error('Amplitude must be positive'));return}el.value=Number(value.toPrecision(12));el.dispatchEvent(new Event('change'))};
async function api(path,data){let r=await fetch(path,{method:data===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-FRA-Token':token},body:data===undefined?undefined:JSON.stringify(data)});let j=await r.json();if(!r.ok)throw Error(j.error||r.statusText);return j}
function fail(e){$('warnings').textContent=e.message}
async function start(single){try{let c=readConfig();if(single){c.stop_frequency=c.start_frequency;c.points=1}await api('/api/start',c);lastRevision=-1;await poll()}catch(e){fail(e)}}
$('start').onclick=()=>start(false);$('single').onclick=()=>start(true);$('stop').onclick=async()=>{try{await api('/api/stop',{});$('state').textContent='Stopping — waiting for cleanup'}catch(e){fail(e)}};
$('savePreset').onclick=()=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(readConfig(),null,2)],{type:'application/json'}));a.download='fra-preset.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
$('loadPreset').onchange=async e=>{try{const c=JSON.parse(await e.target.files[0].text());const checked=await api('/api/validate',c);populate(checked)}catch(e){fail(e)}};
async function poll(){try{let s=await api('/api/status');$('start').disabled=$('single').disabled=s.running;$('stop').disabled=!s.running;for(const button of document.querySelectorAll('.amplitude-buttons button'))button.disabled=s.running;for(const e of $('controls').querySelectorAll('input,select'))e.disabled=s.running;let r=s.result;$('state').textContent=s.running?'Measuring '+(s.frequency_hz||'')+' Hz':r?.status||'Idle';$('progress').max=s.total||1;$('progress').value=s.completed||0;if(!r)return;$('trust').textContent=r.simulation?'SIMULATION / UNTRUSTED':r.trust_state;let p=r.points.at(-1);if(p){const v=(x,u)=>x==null?'—':Number(x).toPrecision(6)+' '+u;$('stats').textContent=`AWG set    ${v(r.config.amplitude*1000,'mVpp')}   Readback ${v(p.source_settings?.state?.vpp==null?null:p.source_settings.state.vpp*1000,'mVpp')}\nFrequency  ${v(p.frequency_hz,'Hz')}\nGain       ${v(p.gain_db,'dB')}      Phase ${v(p.phase_deg,'deg')}\nVin        ${v(p.vin_rms==null?null:p.vin_rms*1000,'mVrms')}   Vout ${v(p.vout_rms==null?null:p.vout_rms*1000,'mVrms')}\nScope rate ${v(p.sample_rate_hz,'Sa/s')}  Record ${p.record_length??'—'}\nAverages   ${p.averages}/${p.requested_averages}      Status ${p.status.toUpperCase()}`}
$('warnings').textContent=[...(r.errors||[]),...r.points.filter(p=>p.status!=='ok').map(p=>`${p.frequency_hz} Hz: ${p.status.toUpperCase()} — ${p.warnings.join('; ')}`)].join('\n');$('details').textContent=JSON.stringify({identities:r.identities,cleanup:r.cleanup},null,2);if(lastRevision!==s.revision){$('plot').src='/api/export/svg?rev='+s.revision;lastRevision=s.revision}}catch(e){fail(e)}}
api('/api/config').then(c=>{defaults=c;populate(c);poll();setInterval(poll,500)}).catch(fail);
</script></html>'''
